(()=>{const key='fordcargo-privacy-choice';let choice;try{choice=localStorage.getItem(key)}catch{}if(!choice){const box=document.createElement('aside');box.className='privacy-notice';box.setAttribute('aria-label','Preferințe de confidențialitate');const p=document.createElement('p');p.textContent='Folosim doar funcții necesare și preferința de limbă. Harta Google se încarcă numai când o soliciți. Nu folosim cookie-uri publicitare.';const link=document.createElement('a');link.href='/politici/cookies/';link.textContent='Politica de Cookies';box.append(p,link);for(const [label,value]of [['Doar necesare','necessary'],['Accept conținut extern','external']]){const b=document.createElement('button');b.textContent=label;b.type='button';b.addEventListener('click',()=>{try{localStorage.setItem(key,value)}catch{}box.remove()});box.append(b)}document.body.append(box)}})();
(()=>{const text='Bună ziua! Vă contactez de pe fordcargo.ro. Doresc informații despre o piesă.';document.querySelectorAll('a[href^="https://wa.me/40733357357"]').forEach(link=>{const url=new URL(link.href);if(!url.searchParams.has('text')){url.searchParams.set('text',text);link.href=url.href}})})();
